/**
 * kon-brain
 *
 * Agent memory: notes with an owner (private by default, optionally shared), connections with provenance, claims with evidence, OKF export and graphify import.
 */
export interface BrainApi {
  /**
   * Add a claim with evidence to your note
   *
   * Ties a statement of YOUR note to its evidence: an existing source (`sourceId`) or the evidence itself (`source`: title, content, uri), captured as an immutable, content-addressed source. Records the source's SHA-256 and an optional range (`line`: 1-based inclusive; `char`: 0-based, end exclusive). Idempotent by (note, statement, source hash). The response never includes the source's content.
   *
   * REST: `POST /api/brain/memory/claims` · scope `kon:brain:add-claim`
   * idempotent (safe to retry) · MCP tool `brain_claim_add`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly addClaim: Operation<AddClaimParams, AddClaimResponse>;
  /**
   * Connect two notes
   *
   * Connects two notes you can see. Idempotent by (source, target, relationType): repeating it returns the existing connection. `origin` defaults to MANUAL with confidence 1.
   *
   * REST: `POST /api/brain/memory/connections` · scope `kon:brain:connect`
   * idempotent (safe to retry) · MCP tool `brain_connect`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly connect: Operation<ConnectParams, ConnectResponse>;
  /**
   * Delete a memory note
   *
   * Deletes YOUR note (and, in cascade, its connections and claims). A shared note of someone else is 403; one you cannot see, 404. Sensible: an agent under human approval gets a proposal (202) instead.
   *
   * REST: `DELETE /api/brain/memory/notes/{id}` · scope `kon:brain:delete-note`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `brain_note_delete`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly deleteNote: Operation<DeleteNoteParams, DeleteNoteResponse>;
  /**
   * Export to Open Knowledge Format v0.2
   *
   * The notes you can see (or `noteIds`, comma-separated, at most 200 per call) as an OKF v0.2 bundle: `files[]` with paths and Markdown (YAML frontmatter: type, title, tags, status, generated, verified, sources; claims as footnotes), plus a root index.md with okf_version "0.2". A longer list is a 422; a URL over the HTTP server's header limit never reaches the API and gets an empty 431.
   *
   * REST: `GET /api/brain/memory/export/okf` · scope `kon:brain:export-okf`
   * idempotent (safe to retry) · MCP tool `brain_export_okf`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly exportOkf: Operation<ExportOkfParams, ExportOkfResponse>;
  /**
   * Import a graphify graph.json
   *
   * Loads a graph.json produced by graphify into YOUR memory: each node is a note with key `graphify:<namespace>:<node id>` (re-importing updates the same notes), each link a connection keeping graphify's EXTRACTED/INFERRED as `origin` and `confidence_score` as `confidence` (AMBIGUOUS → INFERRED, flagged). Checks `graph.schema_version`: absent = legacy format (warning), 1 = supported, anything else = 422 unless `allowUnknownSchemaVersion`. At most 5000 nodes and 20000 links per call.
   *
   * REST: `POST /api/brain/memory/import/graphify` · scope `kon:brain:import-graphify`
   * idempotent (safe to retry) · MCP tool `brain_import_graphify`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly importGraphify: Operation<ImportGraphifyParams, ImportGraphifyResponse>;
  /**
   * Lint claims (mark stale evidence)
   *
   * Deterministic (no AI): re-checks every claim you can see and stores fresh|stale on the ones you may write. A claim is stale when its source was re-captured with another hash (same uri), was deleted, or its range no longer fits.
   *
   * REST: `POST /api/brain/memory/lint` · scope `kon:brain:lint`
   * idempotent (safe to retry) · MCP tool `brain_lint`
   * Errors: `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly lint: Operation<void, LintResponse>;
  /**
   * List claims with evidence
   *
   * Claims (statement + source + the source's SHA-256 + optional range) of the notes you can see. `status=stale` lists the ones whose evidence changed.
   *
   * REST: `GET /api/brain/memory/claims` · scope `kon:brain:list-claims`
   * idempotent (safe to retry) · MCP tool `brain_claims`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listClaims: Operation<ListClaimsParams, ListClaimsResponse>;
  /**
   * List memory notes
   *
   * Notes you can see, most recently updated first. `mine=true` keeps only your own; `keyPrefix` filters by the keys you chose.
   *
   * REST: `GET /api/brain/memory/notes` · scope `kon:brain:list-notes`
   * idempotent (safe to retry) · MCP tool `brain_list`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listNotes: PageableOperation<ListNotesParams, ListNotesResponse, ListNotesItem>;
  /**
   * Connections of a note
   *
   * The connections of a note you can see whose other end you can also see, with provenance: `origin` EXTRACTED (explicit in a source), INFERRED (similarity or a model's guess) or MANUAL (asserted through the API), and `confidence` in [0, 1].
   *
   * REST: `GET /api/brain/memory/notes/{id}/connections` · scope `kon:brain:note-connections`
   * idempotent (safe to retry) · MCP tool `brain_connections`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly noteConnections: Operation<NoteConnectionsParams, NoteConnectionsResponse>;
  /**
   * Read a memory note
   *
   * One note you can see, with its connections (each with `origin` EXTRACTED|INFERRED|MANUAL and `confidence`) and its claims (each with its evidence and fresh|stale status). 404 if it does not exist or is not visible to you.
   *
   * REST: `GET /api/brain/memory/notes/{id}` · scope `kon:brain:read-note`
   * idempotent (safe to retry) · MCP tool `brain_read`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly readNote: Operation<ReadNoteParams, ReadNoteResponse>;
  /**
   * Search memory
   *
   * Notes nearest to `q` among those you can see (yours, your agents' if you sign for them, and shared ones). The default embeddings are LEXICAL (a term-frequency hash: shared words, not meaning) and `embedding.mode` says so; only notes embedded with the same provider are compared.
   *
   * REST: `GET /api/brain/memory/search` · scope `kon:brain:search`
   * idempotent (safe to retry) · MCP tool `brain_search`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly search: Operation<SearchParams, SearchResponse>;
  /**
   * Re-verify a claim
   *
   * Re-checks your claim against its source: fresh (and recorded as verified by you, now) or stale with the reason. With `rebind: true` and a newer source for the same uri, the claim moves to it — you assert the statement still holds there.
   *
   * REST: `POST /api/brain/memory/claims/{id}/verify` · scope `kon:brain:verify-claim`
   * idempotent (safe to retry) · MCP tool `brain_claim_verify`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly verifyClaim: Operation<VerifyClaimParams, VerifyClaimResponse>;
  /**
   * Write a memory note (idempotent by key)
   *
   * Creates or updates YOUR note with this `key` (keys are per owner: another agent's `key` is another note). Writing the same content again changes nothing (`outcome: unchanged`). Private by default; `visibility: shared` lets the team and other agents read it (never write it).
   *
   * REST: `PUT /api/brain/memory/notes` · scope `kon:brain:write-note`
   * idempotent (safe to retry) · MCP tool `brain_note_write`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly writeNote: Operation<WriteNoteParams, WriteNoteResponse>;
}
